import json,urllib.request,urllib.parse,subprocess,datetime
base='http://127.0.0.1:17448'
def get(path,t=4):
 with urllib.request.urlopen(base+path,timeout=t) as r:return json.load(r)
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'scope':'R51_EXACT_EXISTING_TAB_PREVIEW_ONLY'}
head=subprocess.run(['git.exe','-C',r'E:\WebAIBridge','rev-parse','HEAD'],capture_output=True,text=True,timeout=5).stdout.strip()
out['head']=head
if head!='5da11c6b2a3eedea1878c9fe17f3af3aa6d8bd03':raise RuntimeError('unexpected_live_sha')
operator=get('/api/operator-lifecycle');wd=get('/api/supervisor-watchdog?detect=0').get('config',{});health=get('/api/health')
