safe=(operator.get('queuePaused') is True and wd.get('mode')=='off' and wd.get('enabled') is False and wd.get('allowAutonomousSend') is False and wd.get('autoContinueEnabled') is False and q.get('active')==0 and q.get('queued')==2)
out['safety']={'passed':safe,'queuePaused':operator.get('queuePaused'),'watchdogMode':wd.get('mode'),'activeAssignments':q.get('active'),'queuedHeld':q.get('queued')}
if not safe:raise RuntimeError('freeze_gate_failed')
chats=get('/api/supervisor-watchdog/managed-chats?inspect=0').get('chats',[])
out['chats']=[]
for c in chats:
 row={'name':c.get('name'),'id':c.get('id')}
 if c.get('name') in ('Bridge','Media','Creator','Growth','Native MCP'):
  path='/api/supervisor-watchdog/managed-chats/'+urllib.parse.quote(c['id'],safe='')+'/wake-preview'
  try:
   d=get(path,t=4)
   row.update({'state':d.get('state'),'targetId':d.get('exactTargetId'),'targetCount':d.get('exactTargetCount'),'requiredConfirmation':d.get('requiredConfirmation'),'focusChange':d.get('foregroundFocusWillChange'),'noNavigation':d.get('navigationPerformed') is False})
  except Exception as e:row.update({'state':'PREVIEW_FAILED','reason':type(e).__name__})
 out['chats'].append(row)
print(json.dumps(out,ensure_ascii=True)[:6500])
